# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESMÂ-İ HÜSNÂ (أَسْمَاءُ اللّٰهِ الْحُسْنَى): ANLAM VE TECELLİLERİ</text>\n  <rect x="25" y="50" width="152" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="101" y="78" text-anchor="middle" font-size="16" font-weight="bold" fill="#1d4ed8">اَلْبَارِئُ</text>\n  <text x="101" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">el-Bâri\'</text>\n  <text x="35" y="125" font-size="10.5" fill="#334155">• Varlıkları örneksiz,</text>\n  <text x="35" y="142" font-size="10.5" fill="#334155">kusursuz ve birbirine</text>\n  <text x="35" y="159" font-size="10.5" fill="#334155">uyumlu yaratan.</text>\n  <text x="35" y="185" font-size="10" font-weight="bold" fill="#1d4ed8">بَرَأَ اللّٰهُ الْخَلْقَ</text>\n  <rect x="192" y="50" width="152" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="268" y="78" text-anchor="middle" font-size="16" font-weight="bold" fill="#b91c1c">اَلْجَبَّارُ</text>\n  <text x="268" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">el-Cebbâr</text>\n  <text x="202" y="125" font-size="10.5" fill="#334155">• Kırılanları onaran,</text>\n  <text x="202" y="142" font-size="10.5" fill="#334155">eksikleri tamamlayan,</text>\n  <text x="202" y="159" font-size="10.5" fill="#334155">iradesini yürüten.</text>\n  <text x="202" y="185" font-size="10" font-weight="bold" fill="#b91c1c">يَجْبُرُ اللّٰهُ الْقُلُوبَ</text>\n  <rect x="359" y="50" width="152" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="435" y="78" text-anchor="middle" font-size="16" font-weight="bold" fill="#15803d">اَلْحَكِيمُ</text>\n  <text x="435" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">el-Hakîm</text>\n  <text x="369" y="125" font-size="10.5" fill="#334155">• Her işi, emri ve</text>\n  <text x="369" y="142" font-size="10.5" fill="#334155">yaratması hikmetli,</text>\n  <text x="369" y="159" font-size="10.5" fill="#334155">yerli yerinde olan.</text>\n  <text x="369" y="185" font-size="10" font-weight="bold" fill="#15803d">اَللّٰهُ حَكِيمٌ عَلِيمٌ</text>\n  <rect x="526" y="50" width="150" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="601" y="78" text-anchor="middle" font-size="16" font-weight="bold" fill="#a16207">اَلرَّزَّاقُ</text>\n  <text x="601" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">er-Rezzâk</text>\n  <text x="536" y="125" font-size="10.5" fill="#334155">• Bütün canlılara</text>\n  <text x="536" y="142" font-size="10.5" fill="#334155">maddi-manevi bol</text>\n  <text x="536" y="159" font-size="10.5" fill="#334155">rızık ihsan eden.</text>\n  <text x="536" y="185" font-size="10" font-weight="bold" fill="#a16207">يَرْزُقُ اللّٰهُ الْعِبَادَ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSİM CÜMLESİ (اَلْجُمْلَةُ الِاسْمِيَّةُ) VE FİİL CÜMLESİ (اَلْجُمْلَةُ الْفِعْلِيَّةُ)</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İsim Cümlesi: Mübtedâ + Haber</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• İsimle başlar; iki temel ögesi vardır:</text>\n  <text x="60" y="122" font-size="10.5" font-weight="bold" fill="#1e40af">اَلْمُبْتَدَأُ (Mübtedâ) + اَلْخَبَرُ (Haber)</text>\n  <text x="50" y="146" font-size="11" fill="#334155">• İkisi de merfûdur (damme / ötre alır):</text>\n  <text x="60" y="168" font-size="11.5" font-weight="bold" fill="#1d4ed8">اَللّٰهُ رَزَّاقٌ  /  اَللّٰهُ هُوَ الْحَكِيمُ</text>\n  <text x="60" y="190" font-size="10.5" fill="#475569">• Mübtedâ marife (belirli), haber genellikle</text>\n  <text x="60" y="206" font-size="10.5" fill="#475569">nekra (belirsiz) olur ve sayı-cinsiyette uyar.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Fiil Cümlesi: Fiil + Fâil + Mef\'ûlün Bih</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Fiille başlar; temel ögeleri:</text>\n  <text x="390" y="122" font-size="10.5" font-weight="bold" fill="#166534">فِعْلٌ (Fiil) + فَاعِلٌ (Özne) + مَفْعُولٌ بِهِ (Nesne)</text>\n  <text x="380" y="146" font-size="11" fill="#334155">• Fâil merfû (ötre), mef\'ûl mansûb (üstün):</text>\n  <text x="390" y="168" font-size="11.5" font-weight="bold" fill="#15803d">يَرْزُقُ اللّٰهُ الْعِبَادَ  /  خَلَقَ اللّٰهُ الْإِنْسَانَ</text>\n  <text x="390" y="190" font-size="10.5" fill="#475569">• اللّٰهُ : Fâil (merfû - damme)</text>\n  <text x="390" y="206" font-size="10.5" fill="#475569">• الْعِبَادَ : Mef\'ûlün bih (mansûb - fetha)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN AYETLERİNDE DÖRT GÜZEL İSMİN GEÇTİĞİ ÖRNEKLER</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Haşr Suresi 23-24. Ayetler</text>\n  <text x="50" y="105" font-size="12" font-weight="bold" fill="#854d0e">هُوَ اللّٰهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ</text>\n  <text x="50" y="128" font-size="10.5" fill="#334155">&quot;O, yaratan (el-Hâlık), kusursuzca var</text>\n  <text x="50" y="144" font-size="10.5" fill="#334155">eden (el-Bâri\'), şekil veren (el-Musavvir)</text>\n  <text x="50" y="160" font-size="10.5" fill="#334155">Allah\'tır. En güzel isimler O\'nundur...&quot;</text>\n  <text x="50" y="185" font-size="11" font-weight="bold" fill="#854d0e">اَلْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ (Haşr, 23)</text>\n  <text x="50" y="205" font-size="11" font-weight="bold" fill="#854d0e">وَ هُوَ الْعَزِيزُ الْحَكِيمُ (Haşr, 24)</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Zâriyât Suresi 58. Ayet</text>\n  <text x="380" y="105" font-size="12" font-weight="bold" fill="#991b1b">إِنَّ اللّٰهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ</text>\n  <text x="380" y="130" font-size="10.5" fill="#334155">&quot;Şüphesiz Allah, rızık verenlerin en</text>\n  <text x="380" y="146" font-size="10.5" fill="#334155">güçlüsü (er-Rezzâk), pek kudretli ve</text>\n  <text x="380" y="162" font-size="10.5" fill="#334155">sapasağlam kuvvet sahibidir.&quot;</text>\n  <text x="380" y="190" font-size="10.5" font-weight="bold" fill="#991b1b">• الرَّزَّاقُ : Mübalağalı ism-i fâil (fa\'âl</text>\n  <text x="390" y="207" font-size="10.5" fill="#475569">vezni — kesintisiz ve bol rızık veren).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
